    const bid = runtime.api.getBidPrice(itemHrid, enhancementLevel);
    const valueRow = document.createElement("div");
    valueRow.textContent = `${runtime.config.isZH ? "市場價值: " : "Market value: "}${fairValue > 0 ? runtime.api.numberFormatter(fairValue) : "-"}`;
